(()=>{
const $=s=>document.querySelector(s),{scenarios,validateDiagram}=BPMNPractice,storageKey='bpmn-praktikum-v1';let state={drafts:{},solved:[],current:scenarios[0].id};try{const saved=JSON.parse(localStorage.getItem(storageKey)||'null');if(saved&&typeof saved==='object')state={...state,...saved,drafts:saved.drafts||{},solved:Array.isArray(saved.solved)?saved.solved:[]}}catch{}
let current=scenarios.find(s=>s.id===state.current)||scenarios[0],modeler,loading=false,selected=null,saveTimer,addCount=0;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const blank=`<?xml version="1.0" encoding="UTF-8"?><bpmn:definitions xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xmlns:bpmn="http://www.omg.org/spec/BPMN/20100524/MODEL" xmlns:bpmndi="http://www.omg.org/spec/BPMN/20100524/DI" xmlns:dc="http://www.omg.org/spec/DD/20100524/DC" id="Definitions_Practice" targetNamespace="https://bpmn.io/schema/bpmn"><bpmn:process id="Process_Practice" isExecutable="false"><bpmn:startEvent id="StartEvent_Practice" name="Начало"/></bpmn:process><bpmndi:BPMNDiagram id="Diagram_Practice"><bpmndi:BPMNPlane id="Plane_Practice" bpmnElement="Process_Practice"><bpmndi:BPMNShape id="StartEvent_Practice_di" bpmnElement="StartEvent_Practice"><dc:Bounds x="170" y="230" width="36" height="36"/></bpmndi:BPMNShape></bpmndi:BPMNPlane></bpmndi:BPMNDiagram></bpmn:definitions>`;
function storeState(){try{localStorage.setItem(storageKey,JSON.stringify(state));$('#draft-status').textContent='Черновик сохранён'}catch{$('#draft-status').textContent='Нет места для сохранения. Скачайте .bpmn'}}
function updateProgress(){$('#bpmn-progress').textContent=state.solved.filter(id=>scenarios.some(s=>s.id===id)).length+' / '+scenarios.length;$('#scenario-select').innerHTML=scenarios.map(s=>`<option value="${s.id}" ${s.id===current.id?'selected':''}>${state.solved.includes(s.id)?'✓ ':''}${s.level==='Экспертный'?'Эксперт · ':''}${esc(s.title)}</option>`).join('')}
function renderScenario(){state.current=current.id;updateProgress();$('#scenario-title').textContent=current.title;$('#scenario-story').textContent=current.story;$('#scenario-level').textContent=current.level;$('#scenario-area').textContent=current.area;$('#scenario-tasks').innerHTML=current.tasks.map(t=>'<li>'+esc(t)+'</li>').join('');$('#scenario-hint').textContent=current.hint;$('#scenario-elements').innerHTML=current.graph?'<h3>Шлюзы и конечные события</h3><ul>'+current.graph.nodes.filter(n=>['xor','and','end'].includes(n.type)).map(n=>'<li><strong>'+({xor:'XOR',and:'AND',end:'Конец'}[n.type])+'</strong> · '+esc(n.name)+'</li>').join('')+'</ul>':'';$('#scenario-rules').textContent=current.rules||(current.pattern==='sequence'?'Постройте один последовательный процесс: 1 начало, 3 задачи, 1 конец.':current.pattern==='choice'?'Используйте 1 XOR-шлюз и 2 конечных события. Подпишите ветки «Да» и «Нет».':'Используйте 2 AND-шлюза: разделение и синхронизацию. 1 начало и 1 конец.');document.querySelectorAll('.scenario-panel details').forEach(d=>d.open=false);clearValidation()}
function clearValidation(){$('#validation').innerHTML='<div class="validation-intro">Схема готова к работе</div><p>Добавляйте элементы и соединяйте их. Когда закончите, нажмите «Проверить схему».</p>'}
function statusError(text){$('#validation').innerHTML='<div class="check-title">'+esc(text)+'</div>'}
async function saveDraft(){if(!modeler||loading)return;const id=current.id;try{const {xml}=await modeler.saveXML({format:true});state.drafts[id]=xml;storeState()}catch{$('#draft-status').textContent='Не удалось сохранить. Попробуйте скачать .bpmn'}}
function setLoading(value){loading=value;document.querySelectorAll('.drawing-panel button,.quick-tools button,#scenario-select,#random-scenario').forEach(b=>b.disabled=value);$('#canvas').style.pointerEvents=value?'none':'';if(!value)updateSelection(selected)}
async function openScenario(s,{reset=false,initial=false}={}){if(loading)return;clearTimeout(saveTimer);if(!initial)await saveDraft();setLoading(true);current=s;addCount=0;selected=null;renderScenario();try{await modeler.importXML(reset?blank:state.drafts[s.id]||blank);modeler.get('canvas').zoom('fit-viewport');if(reset){state.drafts[s.id]=blank;state.solved=state.solved.filter(id=>id!==s.id);updateProgress()}storeState()}catch{statusError('Не удалось открыть черновик. Скачайте его ниже или начните заново.');$('#draft-status').textContent='Ошибка загрузки черновика'}finally{setLoading(false);updateSelection(null)}}
function updateSelection(element){selected=element;const editable=!!element&&element.type!=='bpmn:Process';$('#element-name').disabled=!editable;$('#rename').disabled=!editable;$('#element-name').value=editable?(element.businessObject?.name||''):'';$('#selection-description').textContent=editable?'Название выбранного элемента':'Выберите элемент, чтобы изменить название'}
function rename(){if(selected&&!loading){modeler.get('modeling').updateLabel(selected,$('#element-name').value.trim())}}
function getGraph(){const elements=modeler.get('elementRegistry').getAll().filter(e=>!e.labelTarget);const flows=elements.filter(e=>e.type==='bpmn:SequenceFlow').map(e=>({source:e.source.id,target:e.target.id,name:e.businessObject.name||''}));const nodes=elements.filter(e=>e.type!=='bpmn:Process'&&e.type!=='bpmn:SequenceFlow').map(e=>{const bo=e.businessObject;return {id:e.id,name:bo?.name||'',type:e.type==='bpmn:StartEvent'?'start':e.type==='bpmn:EndEvent'?'end':e.type==='bpmn:ExclusiveGateway'?'xor':e.type==='bpmn:ParallelGateway'?'and':bo?.$instanceOf('bpmn:Task')?'task':'unsupported'}});return {nodes,flows}}
async function check(){if(loading)return;const {nodes,flows}=getGraph();const result=validateDiagram(nodes,flows,current);$('#validation').innerHTML=`<div class="${result.passed?'success-title':'check-title'}">${result.passed?'✓ Сценарий решён! Все требования выполнены.':'Проверка: '+result.checks.filter(c=>c.pass).length+' из '+result.checks.length+' требований'}</div><ul>${result.checks.map(c=>`<li class="${c.pass?'pass':'fail'}">${c.pass?'✓':'○'} ${esc(c.label)}</li>`).join('')}</ul>`;if(result.passed&&!state.solved.includes(current.id)){state.solved.push(current.id);updateProgress()}await saveDraft();return result}
function download(text,name){const url=URL.createObjectURL(new Blob([text],{type:'application/xml'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
const translations={'Activate the hand tool':'Перемещение холста','Activate the lasso tool':'Выделить область','Activate the create/remove space tool':'Добавить или убрать пространство','Activate the global connect tool':'Соединить элементы','Create start event':'Начальное событие','Create intermediate/boundary event':'Промежуточное событие','Create end event':'Конечное событие','Create gateway':'Шлюз','Create task':'Задача','Create expanded sub-process':'Подпроцесс','Create pool/participant':'Пул участника','Create group':'Группа','Append end event':'Добавить конец','Append gateway':'Добавить шлюз','Append task':'Добавить задачу','Append intermediate/boundary event':'Добавить событие','Change type':'Изменить тип','Connect using Sequence/MessageFlow or Association':'Соединить элементы','Remove':'Удалить','Exclusive gateway':'Исключающий шлюз (XOR)','Parallel gateway':'Параллельный шлюз (AND)','Task':'Задача','Start event':'Начальное событие','End event':'Конечное событие'};
function translate(template,replacements){let text=translations[template]||template;for(const [key,value] of Object.entries(replacements||{}))text=text.replaceAll('{'+key+'}',value);return text}
async function initialize(){if(typeof BpmnJS==='undefined'){statusError('Редактор не загрузился. Обновите страницу.');$('#draft-status').textContent='Ошибка загрузки';return}modeler=new BpmnJS({container:'#canvas',additionalModules:[{translate:['value',translate]}]});modeler.on('selection.changed',e=>updateSelection(e.newSelection.length===1?e.newSelection[0]:null));modeler.on('commandStack.changed',()=>{if(loading)return;clearValidation();$('#draft-status').textContent='Сохраняем…';clearTimeout(saveTimer);saveTimer=setTimeout(saveDraft,350)});await openScenario(current,{initial:true});
$('#scenario-select').onchange=e=>openScenario(scenarios.find(s=>s.id===e.target.value));$('#random-scenario').onclick=()=>{const candidates=scenarios.filter(s=>s.id!==current.id&&!state.solved.includes(s.id));const choices=candidates.length?candidates:scenarios.filter(s=>s.id!==current.id);openScenario(choices[Math.floor(Math.random()*choices.length)])};$('#check-diagram').onclick=check;$('#rename').onclick=rename;$('#element-name').onkeydown=e=>{if(e.key==='Enter')rename()};$('#undo').onclick=()=>modeler.get('commandStack').undo();$('#redo').onclick=()=>modeler.get('commandStack').redo();$('#zoom-in').onclick=()=>{const c=modeler.get('canvas');c.zoom(Math.min(3,c.zoom()*1.2))};$('#zoom-out').onclick=()=>{const c=modeler.get('canvas');c.zoom(Math.max(.2,c.zoom()/1.2))};$('#fit').onclick=()=>modeler.get('canvas').zoom('fit-viewport');$('#reset-diagram').onclick=()=>$('#reset-dialog').showModal();$('#cancel-reset').onclick=()=>$('#reset-dialog').close();$('#confirm-reset').onclick=()=>{$('#reset-dialog').close();openScenario(current,{reset:true})};$('#export-diagram').onclick=async()=>{try{const {xml}=await modeler.saveXML({format:true});download(xml,current.id+'.bpmn')}catch{if(state.drafts[current.id])download(state.drafts[current.id],current.id+'-draft.bpmn');else statusError('Не удалось скачать схему. Попробуйте ещё раз.')}};
document.querySelectorAll('[data-shape]').forEach(button=>button.onclick=()=>{const canvas=modeler.get('canvas'),v=canvas.viewbox();const shape=modeler.get('elementFactory').createShape({type:button.dataset.shape});const created=modeler.get('modeling').createShape(shape,{x:v.x+v.width*.55+(addCount%3)*35,y:v.y+v.height*.45+(addCount%4)*35},canvas.getRootElement());addCount++;modeler.get('selection').select(created);$('#element-name').focus()});
addEventListener('resize',()=>modeler.get('canvas').resized());
if(document.modelContext?.registerTool){const lifetime=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'check_bpmn_scenario',description:'Check the current BPMN drawing against the selected scenario and show the results.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute:async()=>{if(loading)throw new Error('Diagram is loading');return await check()}},{signal:lifetime.signal})).catch(()=>{});addEventListener('pagehide',()=>lifetime.abort(),{once:true})}catch{}}
}
renderScenario();initialize().catch(()=>{statusError('Не удалось запустить редактор. Обновите страницу.');$('#draft-status').textContent='Ошибка редактора'});
})();
